/* Pohrana se NE prikazuje kao karika u lancu: ne stoji između distribucije i
   potrošača, nego se priključuje na više razina mreže. Zato je zaseban blok
   ispod lanca. */
const STORAGE = {
  ic: 'BESS', c: 'var(--amber)', t: 'Pohrana energije', s: 'Priključuje se na svim razinama mreže',
  d: 'Pohrana ne stoji na jednom mjestu u lancu: priključuje se na razini prijenosa (velike baterije i RHE Velebit), na distribuciji (spremnici uz sunčane elektrane) i sve češće iza brojila, u kućanstvima uz krovni solar. Zajedničko im je da razdvajaju trenutak proizvodnje od trenutka potrošnje.',
  // Broj najavljenih baterijskih projekata je namjerno izostavljen: registri se
  // razlikuju, dio projekata je na distribuciji, a broj se mijenja prebrzo da bi
  // stajao u ugrađenoj konstanti.
  facts: [['270 / 240 MW', 'RHE Velebit turbina / pumpa'], ['~ 75 %', 'iskoristivost pumpnog ciklusa']]
};

(function buildStorage() {
  const box = document.getElementById('storageBox');
  if (!box) return;
  box.innerHTML =
    '<div class="card storage-card" style="--nc:' + STORAGE.c + '">' +
    '<h3><i style="background:' + STORAGE.c + '"></i>' + STORAGE.t + '</h3>' +
    '<p class="storage-sub">' + STORAGE.s + '</p>' +
    '<p>' + STORAGE.d + '</p>' +
    '<div class="facts">' + STORAGE.facts.map(f =>
      '<span><b>' + f[0] + '</b>' + f[1] + '</span>').join('') + '</div></div>';
})();

(function buildChain() {
  const box = $('#chain');
  if (!box) return;
  CHAIN.forEach((n, i) => {
    const b = document.createElement('button');
    b.className = 'node';
    b.style.setProperty('--nc', n.c);
    b.setAttribute('role', 'tab');
    b.innerHTML = '<span class="ic">' + n.ic + '</span><h3>' + n.t + '</h3><p>' + n.s + '</p>';
    b.addEventListener('click', () => select(i));
    box.appendChild(b);
    if (i < CHAIN.length - 1) {
      const l = document.createElement('div');
      l.className = 'lnk';
      l.setAttribute('aria-hidden', 'true');
      l.innerHTML = '<svg viewBox="0 0 34 18"><line x1="0" y1="9" x2="28" y2="9" stroke="' + n.c + '"/><path d="M26 4 L34 9 L26 14" fill="none" stroke="' + n.c + '" stroke-width="2"/></svg>';
      box.appendChild(l);
    }
  });
  function select(i) {
    $$('.node', box).forEach((el, j) => el.classList.toggle('on', i === j));
    const n = CHAIN[i];
    $('#chainDetail').innerHTML =
      '<h3><i style="background:' + n.c + '"></i>' + n.t + '</h3><p>' + n.d + '</p>' +
      '<div class="facts">' + n.facts.map(f => '<div><b>' + f[0] + '</b>' + f[1] + '</div>').join('') + '</div>';
  }
  select(0);
})();

