(function buildMap() {
  const svg = $('#mapSvg');
  if (!svg) return;
  const path = pts => 'M' + pts.map(p => proj(p).map(v => v.toFixed(1)).join(' ')).join(' L ') + ' Z';

  svgEl('text', { x: 120, y: 620, class: 'sea-label' }, svg).textContent = 'JADRANSKO MORE';
  svgEl('text', { x: 640, y: 60,  class: 'cty' }, svg).textContent = 'MAĐARSKA';
  svgEl('text', { x: 200, y: 130, class: 'cty' }, svg).textContent = 'SLOVENIJA';
  svgEl('text', { x: 590, y: 390, class: 'cty' }, svg).textContent = 'BOSNA I HERCEGOVINA';
  svgEl('text', { x: 790, y: 250, class: 'cty' }, svg).textContent = 'SRBIJA';

  // kopno je prvi prsten, ostalo otoci
  svgEl('path', { d: path(LAND[0]), class: 'land' }, svg);
  LAND.slice(1).forEach(i => svgEl('path', { d: path(i), class: 'isle' }, svg));

  // granice županija — vlastiti sloj, može se ugasiti
  const gCnt = svgEl('g', { id: 'gZup', class: 'counties' }, svg);
  COUNTIES.forEach(z => {
    const el = svgEl('path', { d: path(z.r), class: 'county' }, gCnt);
    el.setAttribute('aria-label', z.n);
  });

  // --- vodovi ---
  const gLines = svgEl('g', { id: 'gVod' }, svg);
  LINES.forEach(L => {
    const pts = L.pts.map(p => typeof p === 'string' ? SS[p].ll : p);
    const d = 'M' + pts.map(p => proj(p).map(v => v.toFixed(1)).join(' ')).join(' L ');
    const col = L.kv === 400 ? 'var(--kv400)' : L.kv === 220 ? 'var(--kv220)' : 'var(--kv110)';
    svgEl('path', { d, fill: 'none', stroke: col, 'stroke-width': L.kv === 400 ? 2.6 : 1.8, 'stroke-dasharray': L.dash ? '6 5' : 'none', 'stroke-linecap': 'round' }, gLines);
    if (L.lbl) {
      const e = proj(pts[pts.length - 1]);
      const t = svgEl('text', { x: e[0], y: e[1] - 6, class: 'ic-lbl', 'text-anchor': L.anch || 'middle' }, gLines);
      t.textContent = '⇄ ' + L.lbl;
    }
  });

  const tip = $('#mapTip');
  const detail = $('#mapDetail');
  const showDetail = (name, type, mw, desc, hep) => {
    const T = TYPES[type];
    detail.innerHTML =
      '<span class="tag" style="--tc:' + T.c + '"><i></i>' + T.n + '</span>' +
      (hep ? '<span class="tag owner">HEP</span>' : '') +
      '<h3>' + name + '</h3>' +
      (mw ? '<div class="mw">' + fmt(mw, mw < 10 ? 1 : 0) + ' MW</div>' : '<div class="mw">400 kV čvorište</div>') +
      '<p>' + desc + '</p>';
  };
  const bindTip = (el, label, cb) => {
    el.addEventListener('mousemove', ev => {
      const r = svg.getBoundingClientRect();
      tip.style.left = (ev.clientX - r.left + 10) + 'px';
      tip.style.top = (ev.clientY - r.top + 4) + 'px';
      tip.textContent = label;
      tip.style.opacity = 1;
    });
    el.addEventListener('mouseleave', () => tip.style.opacity = 0);
    el.addEventListener('click', cb);
    el.addEventListener('keydown', ev => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); cb(); } });
  };

  // --- trafostanice ---
  const gTS = svgEl('g', { id: 'gTs' }, svg);
  Object.keys(SS).forEach(k => {
    const s = SS[k], [x, y] = proj(s.ll);
    const g = svgEl('g', { class: 'plant', tabindex: 0, role: 'button', 'aria-label': s.n }, gTS);
    svgEl('rect', { x: x - 5.5, y: y - 5.5, width: 11, height: 11, fill: 'var(--panel)', stroke: 'var(--ink)', 'stroke-width': 2 }, g);
    const t = svgEl('text', { x: x + 9, y: y - 7, class: 'lbl', 'font-weight': 600 }, g);
    t.textContent = s.n.replace('TS ', '');
    bindTip(g, s.n + ' · 400 kV', () => showDetail(s.n, 'ts', 0, s.d));
  });

  // --- elektrane ---
  // prstenovi vlasništva (HEP) idu ISPOD markera, u zasebnom sloju koji se pali chipom
  const gHep = svgEl('g', { id: 'gHep', style: 'display:none' }, svg);
  const groups = {};
  ['hidro', 'termo', 'nuk', 'vjetar', 'sunce', 'geo'].forEach(t => groups[t] = svgEl('g', { id: 'g_' + t }, svg));
  // Nekoliko elektrana dijeli praktički istu lokaciju (Korlat, Boraja/Glunča,
  // Velebit/Jasenice…). Bez razmicanja manji marker nestane ispod većeg i postane
  // neklikabilan. Kratka relaksacija razmiče preklopljene parove; pomak je
  // ograničen na ~8 px pa karta ostaje geografski vjerodostojna.
  const pts = PLANTS.map(p => {
    const [x, y] = proj(p.ll);
    return { x, y, x0: x, y0: y, r: 3.2 + Math.sqrt(p.mw) * 0.42 };
  });
  for (let pass = 0; pass < 40; pass++) {
    for (let i = 0; i < pts.length; i++) for (let j = i + 1; j < pts.length; j++) {
      const a = pts[i], b = pts[j];
      const need = (a.r + b.r) * 0.72;
      let dx = b.x - a.x, dy = b.y - a.y;
      let d = Math.hypot(dx, dy);
      if (d >= need) continue;
      if (d < 0.01) { dx = (i % 2 ? 1 : -1); dy = (j % 2 ? 1 : -1); d = Math.hypot(dx, dy); }
      const push = (need - d) / 2 / d;
      a.x -= dx * push; a.y -= dy * push;
      b.x += dx * push; b.y += dy * push;
    }
    // ne dopusti da marker odluta predaleko od stvarne lokacije
    pts.forEach(q => {
      const dx = q.x - q.x0, dy = q.y - q.y0, d = Math.hypot(dx, dy);
      if (d > 8) { q.x = q.x0 + dx / d * 8; q.y = q.y0 + dy / d * 8; }
    });
  }

  PLANTS.forEach((p, i) => {
    const x = pts[i].x, y = pts[i].y;
    const g = svgEl('g', { class: 'plant', tabindex: 0, role: 'button', 'aria-label': p.n }, groups[p.t]);
    const r = pts[i].r;
    if (p.hep) svgEl('circle', { cx: x, cy: y, r: (r + 3).toFixed(1), fill: 'none',
      stroke: 'var(--ink)', 'stroke-width': 1, 'stroke-opacity': 0.55 }, gHep);
    // pogon izvan rada (st:'off'): šuplji krug — lokacija ostaje, proizvodnja ne
    // izgrađeno, još ne na mreži (st:'soon'): blijeda ispuna s isprekidanim rubom
    const off = p.st === 'off', soon = p.st === 'soon';
    svgEl('circle', { cx: x, cy: y, r: r.toFixed(1), class: off ? 'st-off' : soon ? 'st-soon' : '',
      fill: off ? 'none' : TYPES[p.t].c,
      stroke: off || soon ? TYPES[p.t].c : 'var(--panel)', 'stroke-width': off || soon ? 1.8 : 1.4,
      'stroke-dasharray': off || soon ? '3 2.5' : 'none' }, g);
    if (p.lbl) {
      const t = svgEl('text', { x: x + r + 4, y: y + 3.5, class: 'lbl' }, g);
      t.textContent = p.n;
    }
    bindTip(g, p.n + ' · ' + fmt(p.mw, p.mw < 10 ? 1 : 0) + ' MW' +
      (p.hep ? ' · HEP' : '') + (off ? ' · izvan pogona' : soon ? ' · još nije na mreži' : ''),
      () => showDetail(p.n, p.t, p.mw, p.d, p.hep));
  });

  // --- filtri ---
  const chipsBox = $('#mapChips');
  Object.keys(TYPES).forEach(k => {
    const T = TYPES[k];
    const b = document.createElement('button');
    b.className = 'chip on' + (T.sq ? ' sqi' : '') + (T.ln ? ' li' : '');
    b.style.setProperty('--cc', T.c);
    b.innerHTML = '<i></i>' + T.n;
    b.setAttribute('aria-pressed', 'true');
    b.addEventListener('click', () => {
      const on = b.classList.toggle('on');
      b.classList.toggle('off', !on);
      b.setAttribute('aria-pressed', on);
      const target = k === 'ts' ? gTS : k === 'vod' ? gLines : groups[k];
      target.style.display = on ? '' : 'none';
    });
    chipsBox.appendChild(b);
  });

  // --- prikaz HEP-ovog portfelja (prsten oko markera) ---
  const bh = document.createElement('button');
  bh.className = 'chip';
  bh.innerHTML = '<i style="background:none;border:1.5px solid var(--ink)"></i>HEP-ove elektrane';
  bh.setAttribute('aria-pressed', 'false');
  bh.title = 'Označi objekte u vlasništvu HEP-a';
  bh.addEventListener('click', () => {
    const on = gHep.style.display === 'none';
    gHep.style.display = on ? '' : 'none';
    bh.classList.toggle('on', on);
    bh.setAttribute('aria-pressed', on);
  });
  chipsBox.appendChild(bh);
})();

/* ============================================================
   03 · KRIVULJE OPTEREĆENJA
   ============================================================ */
/* Krivulje opterećenja iz stvarnih ENTSO-E podataka za HR (satno, prosjek
   2024. i 2025., lokalno vrijeme). Ovo su profili TIPIČNOG dana u sezoni —
   godišnji vrh sustava (~3 200 MW) viši je jer nastaje na pojedinačnim
   ekstremnim danima koje prosjek izglađuje.

   Ranije su krivulje bile procijenjene: ljetni vrh bio je postavljen u 13 h,
   a mjerenja pokazuju da je u 20 h — razlika od sedam sati. */
const LOAD = {
  zima_radni:   [1875,1738,1668,1651,1685,1842,2211,2470,2588,2593,2531,2527,2494,2433,2397,2403,2517,2669,2696,2702,2635,2551,2356,2124],
  zima_vikend:  [1892,1748,1664,1632,1637,1707,1855,1985,2156,2261,2294,2305,2265,2189,2137,2148,2253,2404,2452,2461,2426,2385,2244,2028],
  ljeto_radni:  [1960,1793,1704,1664,1665,1703,1918,2130,2255,2305,2307,2380,2439,2449,2428,2416,2452,2527,2609,2686,2706,2665,2508,2250],
  ljeto_vikend: [1958,1792,1696,1643,1620,1602,1666,1775,1894,1995,2069,2158,2209,2201,2161,2158,2193,2262,2349,2419,2467,2467,2366,2133],
};
const WIND_SHAPE = [0.95,0.9,0.88,0.85,0.83,0.8,0.78,0.75,0.7,0.66,0.62,0.6,0.58,0.6,0.62,0.66,0.72,0.8,0.88,0.95,1.0,1.02,1.0,0.98];
function solarShape(season, h) {
  const [a, b, amp] = season === 'zima' ? [8, 16, 0.5] : [5.5, 20.5, 0.85];
  if (h < a || h > b) return 0;
  return amp * Math.sin(Math.PI * (h - a) / (b - a));
}

(function loadChart() {
  const svg = $('#loadChart');
  if (!svg) return;
  let season = 'zima', day = 'radni';
  const state = () => ({ pv: +$('#pvR').value, w: +$('#wR').value });

  const M = { l: 58, r: 14, t: 16, b: 34 }, W = 780, H = 360;
  const iw = W - M.l - M.r, ih = H - M.t - M.b;

  function render() {
    const { pv, w } = state();
    const load = LOAD[season + '_' + day];
    const sol = load.map((_, h) => pv * solarShape(season, h));
    const wnd = load.map((_, h) => w * WIND_SHAPE[h]);
    const res = load.map((v, h) => v - sol[h] - wnd[h]);

    const yMax = 3400;
    const yMin = Math.min(0, Math.floor(Math.min.apply(null, res) / 500) * 500);
    const X = h => M.l + h / 23 * iw;
    const Y = v => M.t + (yMax - v) / (yMax - yMin) * ih;

    svg.innerHTML = '';
    for (let v = yMin; v <= yMax; v += 500) {
      svgEl('line', { x1: M.l, x2: W - M.r, y1: Y(v), y2: Y(v), stroke: v === 0 ? 'var(--muted)' : 'var(--line)', 'stroke-width': 1 }, svg);
      const t = svgEl('text', { x: M.l - 8, y: Y(v) + 3.5, class: 'ax', 'text-anchor': 'end' }, svg);
      t.textContent = fmt(v);
    }
    for (let h = 0; h <= 24; h += 3) {
      const t = svgEl('text', { x: X(Math.min(h, 23)), y: H - 12, class: 'ax', 'text-anchor': 'middle' }, svg);
      t.textContent = (h % 24) + 'h';
    }
    svgEl('text', { x: M.l - 44, y: M.t + 2, class: 'ax' }, svg).textContent = 'MW';

    // površine OIE: vjetar (dno) + sunce (na vjetar)
    const area = (lowFn, highFn, fill) => {
      let d = 'M' + X(0) + ' ' + Y(lowFn(0));
      for (let h = 0; h < 24; h++) d += ' L' + X(h) + ' ' + Y(highFn(h));
      for (let h = 23; h >= 0; h--) d += ' L' + X(h) + ' ' + Y(lowFn(h));
      // prozirnost trake je u CSS-u (--area-op) jer tamna podloga traži jaču ispunu
      svgEl('path', { d: d + ' Z', class: 'area', fill, stroke: 'none' }, svg);
    };
    area(() => 0, h => wnd[h], 'var(--c-vjetar)');
    area(h => wnd[h], h => wnd[h] + sol[h], 'var(--c-sunce)');

    const line = (arr, color, dash, wdt) => {
      const d = arr.map((v, h) => (h ? 'L' : 'M') + X(h) + ' ' + Y(v)).join(' ');
      svgEl('path', { d, fill: 'none', stroke: color, 'stroke-width': wdt || 2.6, 'stroke-dasharray': dash || 'none', 'stroke-linejoin': 'round' }, svg);
    };
    line(load, 'var(--ink)');
    line(res, 'var(--kv400)', '7 5', 2.2);

    // statistika
    const peak = Math.max.apply(null, load);
    const valley = Math.min.apply(null, load);
    const avg = load.reduce((a, b) => a + b) / 24;
    const resMin = Math.min.apply(null, res);
    const maxShare = Math.max.apply(null, load.map((v, h) => (sol[h] + wnd[h]) / v * 100));
    $('#loadStats').innerHTML =
      '<div class="card stat"><small>Vršno opterećenje</small><b>' + fmt(peak) + ' <u>MW</u></b></div>' +
      '<div class="card stat"><small>Noćni minimum</small><b>' + fmt(valley) + ' <u>MW</u></b></div>' +
      '<div class="card stat"><small>Faktor opterećenja</small><b>' + fmt(avg / peak * 100) + ' <u>%</u></b></div>' +
      '<div class="card stat"><small>Maks. udio vjetra i sunca</small><b>' + fmt(maxShare) + ' <u>%</u></b></div>' +
      '<div class="card stat"><small>Min. rezidualno opt.</small><b>' + fmt(resMin) + ' <u>MW</u></b></div>';
  }

  const seg = (id, cb) => {
    $$('#' + id + ' button').forEach(b => b.addEventListener('click', () => {
      $$('#' + id + ' button').forEach(x => x.classList.remove('on'));
      b.classList.add('on');
      cb(b.dataset.v);
    }));
  };
  seg('segSeason', v => { season = v; render(); });
  seg('segDay', v => { day = v; render(); });
  $('#pvR').addEventListener('input', () => { $('#pvVal').textContent = $('#pvR').value; render(); });
  $('#wR').addEventListener('input', () => { $('#wVal').textContent = $('#wR').value; render(); });
  render();
})();

