(function buildTech() {
  const grid = $('#techGrid');
  if (!grid) return;
  TECH.forEach(t => {
    const card = document.createElement('div');
    card.className = 'card tech';
    card.style.setProperty('--acc-t', t.c);
    card.innerHTML =
      '<button class="tech-head" aria-expanded="false"><span class="sw" style="background:' + t.c + '"></span>' +
      '<h3>' + t.n + '</h3><span class="role">' + t.role + '</span><span class="pm">+</span></button>' +
      '<div class="tech-body">' +
      '<div class="meta"><span>Emisije: <b>' + t.co2 + '</b></span><span><b>' + t.eff + '</b></span></div>' +
      '<p>' + t.how + '</p>' +
      '<div class="pn"><div class="p"><h5>Prednosti</h5><ul>' + t.p.map(x => '<li>' + x + '</li>').join('') + '</ul></div>' +
      '<div class="n"><h5>Nedostaci</h5><ul>' + t.m.map(x => '<li>' + x + '</li>').join('') + '</ul></div></div>' +
      '<div class="hr-ctx">' + t.hr + '</div></div>';
    const head = card.querySelector('.tech-head');
    head.addEventListener('click', () => {
      const open = card.classList.toggle('open');
      head.setAttribute('aria-expanded', open);
      head.querySelector('.pm').textContent = open ? '−' : '+';
    });
    grid.appendChild(card);
  });
})();

/* ============================================================
   05 · MERIT ORDER SIMULATOR
   ============================================================ */
(function meritSim() {
  const svg = $('#supplyChart');
  if (!svg) return;
  let hyd = 'prosjek';
  const HYD = {
    suho:    { ror: 250, acc: 700 },
    prosjek: { ror: 550, acc: 1100 },
    vlazno:  { ror: 850, acc: 1400 }
  };

  function fleet() {
    const wind = Math.round(1160 * (+$('#swR').value) / 100);
    const sun = Math.round(1000 * (+$('#spR').value) / 100);
    const imp = +$('#impR').value;
    return [
      { n: 'Vjetar', cap: wind, cost: 0, c: 'var(--c-vjetar)', co2: 0 },
      { n: 'Sunce', cap: sun, cost: 0.5, c: 'var(--c-sunce)', co2: 0 },
      { n: 'Protočne HE', cap: HYD[hyd].ror, cost: 3, c: 'var(--c-hidro-2)', co2: 0 },
      { n: 'NE Krško (HR udio)', cap: 348, cost: 50, c: 'var(--c-nuk)', co2: 0 },
      { n: 'Akumulacijske HE', cap: HYD[hyd].acc, cost: 62, c: 'var(--c-hidro)', co2: 0 },
      { n: 'Uvoz', cap: 1600, cost: imp, c: 'var(--muted)', co2: 0.30 },
      { n: 'TE Plomin (ugljen)', cap: 199, cost: 96, c: 'var(--c-ugljen)', co2: 0.95 },
      { n: 'Plinske TE', cap: 850, cost: 122, c: 'var(--c-termo)', co2: 0.37 }
    ].filter(u => u.cap > 0).sort((a, b) => a.cost - b.cost);
  }

  function render() {
    const D = +$('#demR').value;
    const units = fleet();
    let rem = D, price = 0, co2 = 0;
    const disp = [];
    for (const u of units) {
      if (rem <= 0) break;
      const p = Math.min(u.cap, rem);
      disp.push({ ...u, p });
      rem -= p;
      price = u.cost;
      co2 += p * u.co2;
    }
    const served = D - Math.max(0, rem);
    const shortage = rem > 0;

    // viškovi ispod cijene ~0: mora li se izvoziti / pumpati?
    const zeroCap = units.filter(u => u.cost < 10).reduce((a, u) => a + u.cap, 0) + 348; // + nuklearna must-run
    let surplus = Math.max(0, zeroCap - D);
    let pump = 0, exp = 0, curt = 0;
    if (surplus > 0) {
      pump = Math.min(240, surplus); surplus -= pump;
      exp = Math.min(1600, surplus); surplus -= exp;
      curt = surplus;
      price = Math.min(price, 5);
    }

    // veliki brojevi
    const impU = disp.find(u => u.n === 'Uvoz');
    $('#rPrice').innerHTML = (shortage ? '&gt; 300' : fmt(price)) + ' <u>€/MWh</u>';
    $('#rXch').textContent = exp > 0 ? 'izvoz ' + fmt(exp) + ' MW' : impU ? 'uvoz ' + fmt(impU.p) + ' MW' : '0 MW';
    $('#rCO2').innerHTML = fmt(co2) + ' <u>t CO₂/h</u>';
    const res = disp.filter(u => ['Vjetar', 'Sunce', 'Protočne HE', 'Akumulacijske HE'].includes(u.n)).reduce((a, u) => a + u.p, 0);
    $('#rRES').innerHTML = fmt(res / served * 100) + ' <u>%</u>';

    // stupčasti prikaz
    $('#dBar').innerHTML = disp.map(u =>
      '<div style="width:' + (u.p / served * 100) + '%;background:' + u.c + '" title="' + u.n + ' ' + fmt(u.p) + ' MW"></div>').join('');
    $('#dLeg').innerHTML = disp.map(u =>
      '<span><i style="background:' + u.c + '"></i>' + u.n + ' · ' + fmt(u.p) + ' MW</span>').join('');

    // krivulja ponude
    const M = { l: 56, r: 14, t: 14, b: 32 }, W = 760, H = 300;
    const iw = W - M.l - M.r, ih = H - M.t - M.b;
    const totCap = units.reduce((a, u) => a + u.cap, 0);
    const yMax = Math.max(160, Math.max.apply(null, units.map(u => u.cost)) + 30);
    const X = mw => M.l + mw / totCap * iw;
    const Y = c => M.t + (yMax - c) / yMax * ih;
    svg.innerHTML = '';
    for (let c = 0; c <= yMax; c += 40) {
      svgEl('line', { x1: M.l, x2: W - M.r, y1: Y(c), y2: Y(c), stroke: 'var(--line)' }, svg);
      svgEl('text', { x: M.l - 8, y: Y(c) + 3.5, class: 'ax', 'text-anchor': 'end' }, svg).textContent = c;
    }
    svgEl('text', { x: M.l - 44, y: M.t, class: 'ax' }, svg).textContent = '€/MWh';
    for (let mw = 0; mw <= totCap; mw += 1000) {
      svgEl('text', { x: X(mw), y: H - 10, class: 'ax', 'text-anchor': 'middle' }, svg).textContent = fmt(mw);
    }
    let cum = 0;
    units.forEach(u => {
      svgEl('rect', { x: X(cum), y: Y(u.cost), width: Math.max(1, X(cum + u.cap) - X(cum)), height: H - M.b - Y(u.cost), fill: u.c, 'fill-opacity': 0.75, stroke: 'var(--panel)', 'stroke-width': 1 }, svg);
      cum += u.cap;
    });
    svgEl('line', { x1: X(D), x2: X(D), y1: M.t, y2: H - M.b, stroke: 'var(--ink)', 'stroke-width': 2, 'stroke-dasharray': '6 4' }, svg);
    svgEl('text', { x: X(D) + 6, y: M.t + 12, class: 'ax', 'font-weight': 600 }, svg).textContent = 'potrošnja ' + fmt(D) + ' MW';
    if (!shortage) {
      svgEl('circle', { cx: X(D), cy: Y(price), r: 5.5, fill: 'var(--kv400)', stroke: 'var(--panel)', 'stroke-width': 2 }, svg);
      svgEl('text', { x: X(D) + 9, y: Y(price) - 8, class: 'ax', fill: 'var(--kv400)', 'font-weight': 600 }, svg).textContent = fmt(price) + ' €/MWh';
    }

    // poruke
    const msgs = [];
    const marg = disp[disp.length - 1];
    if (shortage) msgs.push('<b>Manjak od ' + fmt(D - served) + ' MW!</b> Ni uz maksimalan uvoz potrošnja nije pokrivena. U stvarnosti slijede hitne mjere i vrlo visoke cijene uravnoteženja.');
    else msgs.push('Granična jedinica: <b>' + marg.n + '</b> (' + fmt(marg.cost) + ' €/MWh). Njezin trošak postaje cijena za sve angažirane izvore.');
    if (exp > 0) msgs.push('Jeftina proizvodnja premašuje potrošnju: <b>RHE pumpa ' + fmt(pump) + ' MW</b>, izvozi se ' + fmt(exp) + ' MW' + (curt > 0 ? ', a ' + fmt(curt) + ' MW se ograničava (curtailment)' : '') + '. Cijene padaju prema nuli ili u minus.');
    else if (pump > 0) msgs.push('Višak jeftine energije: RHE Velebit pumpa ' + fmt(pump) + ' MW u gornje jezero.');
    if (impU && impU.p > 0 && !shortage) msgs.push('Uvoz je u voznom redu <b>prije domaćih termoelektrana</b> dok god je jeftiniji od njih — pomaknite cijenu uvoza iznad ~96 €/MWh i gledajte kako se redoslijed mijenja.');
    if (marg && (marg.n === 'Plinske TE' || marg.n === 'TE Plomin (ugljen)')) msgs.push('Cijenu postavlja fosilna jedinica, tipična situacija u večernjem vrhu. Više vjetra, sunca ili hidrologije istisnulo bi je iz voznog reda.');
    if (co2 > 0) msgs.push('Emisije potječu od ' + (disp.filter(u => u.co2 > 0).map(u => u.n).join(', ')) + '. Pretpostavljeni faktori: ugljen 0,95, plin 0,37, uvoz 0,30 t CO₂/MWh.');
    $('#simMsgs').innerHTML = msgs.map(m => '<li>' + m + '</li>').join('');
  }

  [['demR', 'demVal'], ['swR', 'swVal'], ['spR', 'spVal'], ['impR', 'impVal']].forEach(([r, v]) => {
    $('#' + r).addEventListener('input', () => { $('#' + v).textContent = $('#' + r).value; render(); });
  });
  $$('#segHyd button').forEach(b => b.addEventListener('click', () => {
    $$('#segHyd button').forEach(x => x.classList.remove('on'));
    b.classList.add('on');
    hyd = b.dataset.v;
    render();
  }));
  render();
})();

/* ============================================================
   06 · SIMULACIJA FREKVENCIJE (njihajna jednadžba)
   ============================================================ */
(function freqSim() {
  const svg = $('#freqChart');
  if (!svg) return;
  const S = 2600, f0 = 50, T = 60, dt = 0.02, tEvent = 3;

  function simulate(loss, H, fcrMax) {
    const D = 0.02 * S;               // samoregulacija tereta ≈ 2 %/Hz
    const K = fcrMax / 0.2;           // droop: puna FCR na 200 mHz
    const tauF = 2;                   // vremenska konstanta odziva FCR (hidroagregati)
    const Ki = 20;                    // aFRR integrator MW/(Hz·s)
    const aMax = 400;
    const stages = [[49.0, 0.08], [48.8, 0.08], [48.6, 0.08], [48.4, 0.10]]; // UFLS stupnjevi
    const fired = [false, false, false, false];
    let f = f0, pFcr = 0, pAfrr = 0, shed = 0;
    const out = [];
    let nadir = f0, tNadir = 0, rocof0 = 0;
    for (let t = 0; t <= T; t += dt) {
      const dP = t >= tEvent ? -loss : 0;
      const df = f - f0;
      stages.forEach((s, i) => { if (!fired[i] && f < s[0]) { fired[i] = true; shed += s[1] * S; } });
      const target = Math.max(-fcrMax, Math.min(fcrMax, -K * df));
      pFcr += (target - pFcr) / tauF * dt;
      if (t >= tEvent) pAfrr = Math.max(-aMax, Math.min(aMax, pAfrr - Ki * df * dt));
      const imb = dP + shed + pFcr + pAfrr - D * df;
      const dfdt = imb * f0 / (2 * H * S);
      if (t >= tEvent && t < tEvent + dt * 1.5) rocof0 = dfdt;
      f += dfdt * dt;
      if (f < nadir) { nadir = f; tNadir = t; }
      out.push([t, f]);
    }
    return { out, nadir, tNadir, rocof0, fEnd: f, shed };
  }

  function render() {
    const loss = +$('#fLoss').value, H = +$('#fH').value, fcr = +$('#fFcr').value;
    $('#fLossV').textContent = loss;
    $('#fHV').textContent = fmt(H, 1);
    $('#fFcrV').textContent = fcr;
    const r = simulate(loss, H, fcr);

    const M = { l: 60, r: 14, t: 14, b: 32 }, W = 780, Hh = 320;
    const iw = W - M.l - M.r, ih = Hh - M.t - M.b;
    const yMin = Math.min(48.5, Math.floor(r.nadir * 10) / 10 - 0.15), yMax = 50.2;
    const X = t => M.l + t / T * iw;
    const Y = f => M.t + (yMax - f) / (yMax - yMin) * ih;
    svg.innerHTML = '';
    for (let f = Math.ceil(yMin * 5) / 5; f <= yMax + 0.001; f += 0.2) {
      svgEl('line', { x1: M.l, x2: W - M.r, y1: Y(f), y2: Y(f), stroke: 'var(--line)' }, svg);
      svgEl('text', { x: M.l - 8, y: Y(f) + 3.5, class: 'ax', 'text-anchor': 'end' }, svg).textContent = fmt(f, 1);
    }
    for (let t = 0; t <= T; t += 10) {
      svgEl('text', { x: X(t), y: Hh - 10, class: 'ax', 'text-anchor': 'middle' }, svg).textContent = t + ' s';
    }
    // referentne crte
    const refLine = (f, col, lbl) => {
      if (f < yMin) return;
      svgEl('line', { x1: M.l, x2: W - M.r, y1: Y(f), y2: Y(f), stroke: col, 'stroke-width': 1.4, 'stroke-dasharray': '4 4' }, svg);
      svgEl('text', { x: W - M.r - 4, y: Y(f) - 5, class: 'ax', fill: col, 'text-anchor': 'end' }, svg).textContent = lbl;
    };
    refLine(50, 'var(--kv220)', 'f₀ = 50 Hz');
    refLine(49.8, 'var(--amber)', '49,8 · puna FCR');
    refLine(49.0, 'var(--kv400)', '49,0 · 1. stupanj podfrekventnog rasterećenja');
    // ispad
    svgEl('line', { x1: X(tEvent), x2: X(tEvent), y1: M.t, y2: Hh - M.b, stroke: 'var(--muted)', 'stroke-dasharray': '3 4' }, svg);
    svgEl('text', { x: X(tEvent) + 5, y: M.t + 12, class: 'ax' }, svg).textContent = 'ispad −' + loss + ' MW';
    // krivulja
    const d = r.out.filter((_, i) => i % 4 === 0).map((p, i) => (i ? 'L' : 'M') + X(p[0]).toFixed(1) + ' ' + Y(p[1]).toFixed(1)).join(' ');
    svgEl('path', { d, fill: 'none', stroke: 'var(--kv110)', 'stroke-width': 2.6, 'stroke-linejoin': 'round' }, svg);
    // nadir
    svgEl('circle', { cx: X(r.tNadir), cy: Y(r.nadir), r: 5, fill: 'var(--kv400)', stroke: 'var(--panel)', 'stroke-width': 2 }, svg);
    svgEl('text', { x: X(r.tNadir) + 8, y: Y(r.nadir) + 14, class: 'ax', fill: 'var(--kv400)', 'font-weight': 600 }, svg).textContent = 'nadir ' + fmt(r.nadir, 2) + ' Hz';

    $('#fRocof').innerHTML = fmt(r.rocof0, 2) + ' <u>Hz/s</u>';
    $('#fNadir').innerHTML = fmt(r.nadir, 2) + ' <u>Hz</u>';
    $('#fEnd').innerHTML = fmt(r.fEnd, 2) + ' <u>Hz</u>';
    const el = $('#fUfls');
    el.textContent = r.shed > 0 ? 'odbačeno ' + fmt(r.shed) + ' MW' : 'nije aktivirano';
    el.style.color = r.shed > 0 ? 'var(--kv400)' : 'var(--kv220)';
  }

  ['fLoss', 'fH', 'fFcr'].forEach(id => $('#' + id).addEventListener('input', render));
  $('#fRun').addEventListener('click', render);
  render();
})();

/* ============================================================
   EMBED NAČIN — ?embed=1 skriva zaglavlje/podnožje u iframeu
   ============================================================ */
(function embedMode() {
  if (/[?&]embed=1/.test(location.search)) document.documentElement.classList.add('embed');
})();

/* ============================================================
   TEMA — usklađivanje sa stranicom u koju je alat ugrađen

   Bez `data-theme` alat prati OS (@media prefers-color-scheme).
   To nije dovoljno kad čitatelj na WonderingNeutronu ručno prebaci
   temu: njegov izbor gazi OS, a iframe za to ne zna. Zato prima
   temu na dva načina:
     ?theme=dark|light   — stanje u trenutku učitavanja
     postMessage         — naknadni prebačaj, bez ponovnog učitavanja
   Poruka se prihvaća samo ako je oblika {wnTheme:'dark'|'light'};
   sve ostalo se ignorira, pa slučajne poruke s drugih skripti na
   stranici ne mogu promijeniti izgled.
   ============================================================ */
/* ============================================================
   VISINA — javljanje roditeljskom okviru

   Dok je alat živio na istoj domeni, roditelj je visinu čitao izravno iz
   contentDocumenta. Sada je na drugoj domeni (GitHub Pages), pa mu je taj
   pristup zabranjen i visinu mora dobiti od nas. Bez ovoga bi iframe ostao
   na fiksnoj visini iz CSS-a: ili odrezan ili s praznim prostorom ispod.

   Šalje se samo u embed načinu — samostalno otvorena stranica nema kome.
   ============================================================ */
(function javiVisinu() {
  if (!/[?&]embed=1/.test(location.search) || parent === window) return;
  let zadnja = 0;
  const javi = () => {
    // body, ne documentElement: <html> se rasteže na visinu iframea, pa bi
    // mjerio okvir umjesto sadržaja i visina se nikad ne bi smanjila
    const h = Math.max(document.body.scrollHeight, document.body.offsetHeight);
    if (h > 0 && h !== zadnja) {
      zadnja = h;
      parent.postMessage({ wnVisina: h }, '*');
    }
  };
  addEventListener('load', javi);
  addEventListener('resize', javi);
  if (window.ResizeObserver) new ResizeObserver(javi).observe(document.body);
  // alati prekrajaju sadržaj i nakon učitavanja (karta, grafovi, kartice)
  setInterval(javi, 1000);
})();

(function themeSync() {
  const root = document.documentElement;
  const set = t => {
    if (t === 'dark' || t === 'light') root.setAttribute('data-theme', t);
    else root.removeAttribute('data-theme');
  };
  const m = /[?&]theme=(dark|light)/.exec(location.search);
  if (m) set(m[1]);
  addEventListener('message', ev => {
    const d = ev.data;
    if (d && typeof d === 'object' && 'wnTheme' in d) set(d.wnTheme);
  });
})();

/* ============================================================
   KARTA · zoom, pomicanje i animacija tokova
   ============================================================ */
(function mapZoomFlows() {
  const svg = $('#mapSvg');
  const box = document.querySelector('.map-box');
  if (!svg || !box) return;
  const W = 850, H = 720;
  let vb = { x: 0, y: 0, w: W, h: H };
  const apply = () => svg.setAttribute('viewBox', [vb.x, vb.y, vb.w, vb.h].map(v => v.toFixed(1)).join(' '));

  function zoom(f, cx, cy) {
    const nw = Math.min(W, Math.max(W / 6, vb.w * f));
    const nh = nw * H / W;
    if (cx === undefined) { cx = vb.x + vb.w / 2; cy = vb.y + vb.h / 2; }
    vb.x = Math.max(0, Math.min(W - nw, cx - (cx - vb.x) * nw / vb.w));
    vb.y = Math.max(0, Math.min(H - nh, cy - (cy - vb.y) * nh / vb.h));
    vb.w = nw; vb.h = nh;
    apply();
  }
  const toMap = ev => {
    const r = svg.getBoundingClientRect();
    return [vb.x + (ev.clientX - r.left) / r.width * vb.w, vb.y + (ev.clientY - r.top) / r.height * vb.h];
  };
  svg.addEventListener('wheel', ev => {
    ev.preventDefault();
    const [cx, cy] = toMap(ev);
    zoom(ev.deltaY > 0 ? 1.18 : 0.85, cx, cy);
  }, { passive: false });

  let drag = null;
  svg.addEventListener('pointerdown', ev => {
    drag = [ev.clientX, ev.clientY, vb.x, vb.y];
    try { svg.setPointerCapture(ev.pointerId); } catch (e) {}
  });
  svg.addEventListener('pointermove', ev => {
    if (!drag) return;
    const r = svg.getBoundingClientRect();
    vb.x = Math.max(0, Math.min(W - vb.w, drag[2] - (ev.clientX - drag[0]) / r.width * vb.w));
    vb.y = Math.max(0, Math.min(H - vb.h, drag[3] - (ev.clientY - drag[1]) / r.height * vb.h));
    apply();
  });
  ['pointerup', 'pointercancel', 'pointerleave'].forEach(e => svg.addEventListener(e, () => drag = null));

  const z = document.createElement('div');
  z.className = 'zoom-btns';
  z.innerHTML = '<button aria-label="Povećaj">+</button><button aria-label="Smanji">−</button><button aria-label="Cijela karta" style="font-size:13px">⟲</button>';
  const [bi, bo, br] = z.querySelectorAll('button');
  bi.addEventListener('click', () => zoom(0.8));
  bo.addEventListener('click', () => zoom(1.25));
  br.addEventListener('click', () => { vb = { x: 0, y: 0, w: W, h: H }; apply(); });
  box.appendChild(z);

  const chips = $('#mapChips');
  if (chips) {
    const b = document.createElement('button');
    b.className = 'chip';
    b.innerHTML = '<i style="background:var(--kv400)"></i>Animiraj tokove';
    b.setAttribute('aria-pressed', 'false');
    b.title = 'Ilustrativna animacija smjera tokova energije';
    b.addEventListener('click', () => {
      const on = svg.classList.toggle('flow');
      b.classList.toggle('on', on);
      b.setAttribute('aria-pressed', on);
    });
    chips.appendChild(b);
  }
})();

/* ============================================================
   SCENARIJ-LABORATORIJ v2 — birljivi scenariji + vlastiti
   ============================================================ */
(function scenarioLab() {
  const grid = $('#scnGrid');
  if (!grid) return;

  const HYDs = { suho: { ror: 250, acc: 700 }, prosjek: { ror: 550, acc: 1100 }, vlazno: { ror: 850, acc: 1400 } };

  function run(p) {
    const hy = HYDs[p.hyd || 'prosjek'];
    const impCap = p.impCap === undefined ? 1600 : p.impCap;
    const units = [
      { n: 'Vjetar', cap: p.windMW || 0, cost: 0, co2: 0, res: 1 },
      { n: 'Sunce', cap: p.sunMW || 0, cost: 0.5, co2: 0, res: 1 },
      { n: 'Protočne HE', cap: hy.ror, cost: 3, co2: 0, res: 1 },
      p.krsko === false ? null : { n: 'NE Krško', cap: 348, cost: 50, co2: 0 },
      { n: 'Akumulacijske HE', cap: hy.acc, cost: 62, co2: 0, res: 1 },
      p.bess ? { n: 'Pohrana (BESS)', cap: p.bess, cost: 85, co2: 0, res: 1 } : null,
      impCap > 0 ? { n: 'Uvoz', cap: impCap, cost: p.imp === undefined ? 95 : p.imp, co2: 0.30 } : null,
      p.plomin === false ? null : { n: 'TE Plomin', cap: 199, cost: 96, co2: 0.95 },
      { n: 'Plinske TE', cap: 850, cost: 122, co2: 0.37 }
    ].filter(u => u && u.cap > 0).sort((a, b) => a.cost - b.cost);

    let rem = p.dem, price = 0, co2 = 0, resMW = 0, impMW = 0;
    for (const u of units) {
      if (rem <= 0) break;
      const q = Math.min(u.cap, rem);
      rem -= q; price = u.cost; co2 += q * u.co2;
      if (u.res) resMW += q;
      if (u.n === 'Uvoz') impMW = q;
    }
    const served = p.dem - Math.max(0, rem), shortage = rem > 0;
    const zeroCap = (p.windMW || 0) + (p.sunMW || 0) + hy.ror + (p.krsko === false ? 0 : 348);
    let surplus = Math.max(0, zeroCap - p.dem), pump = 0, exp = 0, curt = 0;
    if (surplus > 0) {
      pump = Math.min(240 + (p.bess || 0), surplus); surplus -= pump;
      exp = Math.min(impCap, surplus); surplus -= exp;
      curt = surplus;
      price = 0;
    }
    const totCap = units.reduce((a, u) => a + u.cap, 0);
    return { price, shortage, co2: Math.round(co2), resPct: Math.round(resMW / served * 100), imp: impMW, exp, pump, curt, margin: totCap - p.dem, impCap };
  }

  const sem = r => {
    const price = r.shortage ? ['r', 'cijena > 300'] : r.price >= 110 ? ['r', 'cijena ' + r.price + ' €'] : r.price >= 60 ? ['y', 'cijena ' + r.price + ' €'] : ['g', 'cijena ' + r.price + ' €'];
    const sup = r.shortage ? ['r', 'manjak energije'] : (r.impCap === 0 && r.margin < 700) ? ['y', 'bez uvozne rezerve'] : r.imp > 1000 ? ['y', 'visok uvoz'] : ['g', 'opskrba stabilna'];
    const em = r.co2 >= 500 ? ['r', 'CO₂ ' + fmt(r.co2) + ' t/h'] : r.co2 >= 150 ? ['y', 'CO₂ ' + fmt(r.co2) + ' t/h'] : ['g', 'CO₂ ' + fmt(r.co2) + ' t/h'];
    return [price, sup, em];
  };

  const numsHTML = r =>
    '<span>Cijena <b>' + (r.shortage ? '&gt; 300' : fmt(r.price)) + ' €/MWh</b></span>' +
    '<span>Razmjena <b>' + (r.exp > 0 ? 'izvoz ' + fmt(r.exp) : r.imp > 0 ? 'uvoz ' + fmt(r.imp) : '0') + ' MW</b></span>' +
    '<span>Udio OIE + hidro <b>' + r.resPct + ' %</b></span>' +
    '<span>Emisije <b>' + fmt(r.co2) + ' t CO₂/h</b></span>' +
    (r.curt > 0 ? '<span>Ograničeno <b>' + fmt(r.curt) + ' MW</b></span>' : '') +
    (r.pump > 0 ? '<span>Pohranjuje se <b>' + fmt(r.pump) + ' MW</b></span>' : '');
  const semHTML = r => sem(r).map(x => '<span class="' + x[0] + '">' + x[1] + '</span>').join('');

  const SCN = [
    { n: '1 · Sušna godina + hladni val', short: 'Sušna zima', when: 'Zimska večer, hidrologija podbacila, cijene u regiji visoke.',
      p: { dem: 3200, hyd: 'suho', windMW: 290, sunMW: 100, imp: 180 },
      c: ['Akumulacije čuvaju vodu → domaća hidroproizvodnja prepolovljena.',
          'Manjak pokriva masovan uvoz po 180 €/MWh, cijenu diktira regija, ne Hrvatska.',
          'Emisije se ne vide u domaćoj statistici, ali se "uvoze" kroz regionalni miks.',
          'Upravo ovakve zime dižu godišnju uvoznu ovisnost prema 30 %.'] },
    { n: '2 · Solarno podne 2030. (3,5 GW sunca)', short: 'Solarno podne', when: 'Vedar proljetni dan, niska potrošnja, solar na maksimumu.',
      p: { dem: 2400, hyd: 'prosjek', windMW: 540, sunMW: 2975, imp: 20 },
      c: ['Proizvodnja bez goriva premašuje cijelu potrošnju — cijena pada na nulu (u praksi i u minus).',
          'RHE i baterije pune se do vrha, višak se izvozi dok interkonekcije ne "napune".',
          'Ostatak se mora ograničiti (curtailment), besplatna energija se baca.',
          'Vrijednost pohrane i fleksibilne potrošnje raste brže od vrijednosti novih panela.'] },
    { n: '3 · Izlazak iz ugljena (Plomin ugašen)', short: 'Bez ugljena', when: 'Zimska večer nakon zatvaranja TE Plomin, bez sunca.',
      p: { dem: 2900, hyd: 'prosjek', windMW: 464, sunMW: 0, imp: 110, plomin: false },
      c: ['Nestaje 199 MW bazne domaće proizvodnje — zamjenjuju je uvoz i plin.',
          'Marginalnu cijenu sada postavlja uvoz: domaći račun ovisi o tuđem miksu.',
          'Klimatski dobitak je stvaran samo ako zamjena nije uvezeni ugljen iz regije.',
          'Otvara se pitanje čvrstih niskougljičnih zamjena: pohrana, plin kao prijelaz, dugoročno i nuklearna opcija.'] },
    { n: '4 · Ispad interkonekcija (otočni rad)', short: 'Otočni rad', when: 'Poremećaj u regiji odsiječe Hrvatsku od europske mreže.',
      p: { dem: 2600, hyd: 'prosjek', windMW: 406, sunMW: 300, impCap: 0 },
      c: ['Domaće elektrane još pokrivaju potrošnju — ali bez uvozne rezerve svaki kvar postaje kritičan.',
          'Frekvenciju više ne drži europska inercija od 400+ GW nego samo domaći rotori.',
          'Svaki ispad bloka ide ravno na FCR i podfrekventno rasterećenje → isprobaj alat "Frekvencijski odziv".',
          'Zato se N-1 kriterij i rezerve dimenzioniraju i za najgori dan, ne za prosječan.'] },
    { n: '5 · Elektrifikacija 2035., večernji vrh', short: 'Elektrifikacija', when: 'EV punjači i dizalice topline dižu vrh na 3 400 MW; sunce je zašlo.',
      p: { dem: 3400, hyd: 'prosjek', windMW: 1125, sunMW: 0, imp: 130 },
      c: ['Solar od 3,5 GW navečer daje nulu — vrh nose vjetar, hidro i uvoz.',
          'Večernja rampa postaje strmija nego danas ("pačja krivulja" u punom obliku).',
          'Cijenu postavlja uvoz od 130 €/MWh, elektrificirana potrošnja plaća tuđi vršni trošak.',
          'Bez pohrane, dodatni paneli ovom satu ne pomažu ništa.'] },
    { n: '6 · Elektrifikacija + 1 GW pohrane', short: 'Elektrif. + pohrana', when: 'Isti večernji vrh kao u scenariju 5, ali s 1 GW baterija punjenih podnevnim solarom.',
      p: { dem: 3400, hyd: 'prosjek', windMW: 1125, sunMW: 0, imp: 130, bess: 1000 },
      c: ['Baterije istiskuju uvoz iz voznog reda: podnevni solar isporučen navečer.',
          'Marginalna cijena pada sa 130 na 85 €/MWh, pohrana "izravnava" dan.',
          'Uvoz u vršnom satu: nula. Sustav prolazi vrh domaćim resursima.',
          'Usporedi sa scenarijem 5: ista potrošnja, isti vjetar, razlika je samo pohrana.'] }
  ];

  const results = SCN.map(s => run(s.p));
  const cmp = new Set();
  const cards = [], cardBoxes = [];

  // kartice
  SCN.forEach((s, i) => {
    const r = results[i];
    const card = document.createElement('div');
    card.className = 'card scn';
    card.innerHTML =
      '<h3>' + s.n + '</h3><p>' + s.when + '</p>' +
      '<div class="nums">' + numsHTML(r) + '</div>' +
      '<div class="sem">' + semHTML(r) + '</div>' +
      '<ul class="chainlist">' + s.c.map(x => '<li>' + x + '</li>').join('') + '</ul>' +
      '<label class="cmp"><input type="checkbox"> usporedi</label>';
    const cb = card.querySelector('input');
    cb.addEventListener('change', ev => {
      ev.target.checked ? cmp.add(i) : cmp.delete(i);
      renderCmp();
    });
    grid.appendChild(card);
    cards.push(cb);
    cardBoxes.push(card);
  });

  // birači scenarija (chipovi)
  const pick = $('#scnPick');
  if (pick) SCN.forEach((s, i) => {
    const b = document.createElement('button');
    b.className = 'chip on';
    b.style.setProperty('--cc', 'var(--amber)');
    b.innerHTML = '<i></i>' + s.short;
    b.setAttribute('aria-pressed', 'true');
    b.addEventListener('click', () => {
      const on = b.classList.toggle('on');
      b.classList.toggle('off', !on);
      b.setAttribute('aria-pressed', on);
      cardBoxes[i].style.display = on ? '' : 'none';
      if (!on && cmp.has(i)) { cmp.delete(i); cards[i].checked = false; renderCmp(); }
    });
    pick.appendChild(b);
  });

  // vlastiti scenarij
  let customRes = null;
  const custIds = ['custDem', 'custW', 'custS', 'custB', 'custIP', 'custIC'];
  let custHyd = 'prosjek';
  function renderCustom() {
    if (!$('#custDem')) return;
    custIds.forEach(id => { $('#' + id + 'V').textContent = fmt(+$('#' + id).value); });
    customRes = run({
      dem: +$('#custDem').value, hyd: custHyd,
      windMW: +$('#custW').value, sunMW: +$('#custS').value,
      bess: +$('#custB').value, imp: +$('#custIP').value, impCap: +$('#custIC').value,
      plomin: $('#custPl').checked, krsko: $('#custKr').checked
    });
    $('#custNums').innerHTML = numsHTML(customRes);
    $('#custSem').innerHTML = semHTML(customRes);
    renderCmp();
  }
  if ($('#custDem')) {
    custIds.forEach(id => $('#' + id).addEventListener('input', renderCustom));
    ['custPl', 'custKr'].forEach(id => $('#' + id).addEventListener('change', renderCustom));
    $$('#custHyd button').forEach(b => b.addEventListener('click', () => {
      $$('#custHyd button').forEach(x => x.classList.remove('on'));
      b.classList.add('on');
      custHyd = b.dataset.v;
      renderCustom();
    }));
    $('#custCmp').addEventListener('change', renderCmp);
    renderCustom();
  }

  function renderCmp() {
    const box = $('#cmpBody');
    if (!box) return;
    const rows = Array.from(cmp).sort().map(i => [SCN[i].n, results[i]]);
    if ($('#custCmp') && $('#custCmp').checked && customRes) rows.push(['Vlastiti scenarij', customRes]);
    if (!rows.length) {
      box.innerHTML = '<p class="empty">Označi „usporedi" na dva ili više scenarija za tablicu jedan-pored-drugog.</p>';
      return;
    }
    box.innerHTML = '<table><tr><th>Scenarij</th><th>Cijena €/MWh</th><th>Razmjena MW</th><th>OIE %</th><th>CO₂ t/h</th><th>Ograničeno MW</th><th>Rezerva kap. MW</th></tr>' +
      rows.map(([n, r]) =>
        '<tr><td>' + n + '</td><td>' + (r.shortage ? '&gt;300' : fmt(r.price)) + '</td><td>' +
        (r.exp > 0 ? '+' + fmt(r.exp) : r.imp > 0 ? '−' + fmt(r.imp) : '0') + '</td><td>' + r.resPct + '</td><td>' +
        fmt(r.co2) + '</td><td>' + fmt(r.curt) + '</td><td>' + fmt(r.margin) + '</td></tr>').join('') + '</table>';
  }
  renderCmp();
})();

/* ============================================================
   JALOVA SNAGA · interaktivni trokut snaga
   ============================================================ */
(function powerTriangle() {
  const svg = $('#pfSvg');
  if (!svg) return;
  const R = $('#pfR');

  function render() {
    const pf = +R.value / 100;
    $('#pfVal').textContent = pf.toFixed(2).replace('.', ',');
    const P = 100, S = P / pf, Q = Math.sqrt(S * S - P * P);
    const iPct = (1 / pf - 1) * 100;          // porast struje uz isti P
    const lossPct = (1 / (pf * pf) - 1) * 100; // porast gubitaka (∝ I²)

    // crtanje: hipotenuza S fiksne duljine, trokut se "otvara" s padom cos φ
    const ox = 34, oy = 246, L = 230;
    const Ppx = L * pf, Qpx = L * Math.sin(Math.acos(pf));
    svg.innerHTML = '';
    const ln = (x1, y1, x2, y2, c, w, dash) =>
      svgEl('line', { x1, y1, x2, y2, stroke: c, 'stroke-width': w, 'stroke-linecap': 'round', 'stroke-dasharray': dash || 'none' }, svg);
    ln(ox, oy, ox + Ppx, oy, 'var(--kv220)', 4);
    ln(ox + Ppx, oy, ox + Ppx, oy - Qpx, 'var(--kv400)', 4);
    ln(ox, oy, ox + Ppx, oy - Qpx, 'var(--ink)', 3, '7 5');
    const tx = (x, y, t, c, anch) => {
      const e = svgEl('text', { x, y, class: 'ax', fill: c || 'var(--muted)', 'text-anchor': anch || 'start', 'font-weight': 600 }, svg);
      e.textContent = t;
    };
    tx(ox + Ppx / 2, oy + 16, 'P (radna) = 100', 'var(--kv220)', 'middle');
    tx(ox + Ppx + 8, oy - Qpx / 2 + 4, 'Q = ' + fmt(Q), 'var(--kv400)');
    tx(ox + Ppx / 2 - 14, oy - Qpx / 2 - 10, 'S = ' + fmt(S), 'var(--ink)', 'end');
    // kut φ
    const phi = Math.acos(pf);
    const arcR = 44;
    svgEl('path', { d: 'M ' + (ox + arcR) + ' ' + oy + ' A ' + arcR + ' ' + arcR + ' 0 0 0 ' + (ox + arcR * Math.cos(phi)) + ' ' + (oy - arcR * Math.sin(phi)), fill: 'none', stroke: 'var(--muted)', 'stroke-width': 1.5 }, svg);
    tx(ox + arcR + 8, oy - 12, 'φ = ' + fmt(phi * 180 / Math.PI) + '°');

    $('#pfOut').innerHTML = 'Za istu radnu snagu: prividna snaga <b>S = ' + fmt(S) + ' %</b> od P, struja u vodu <b>+' + fmt(iPct) + ' %</b>, gubici (I²R) <b>+' + fmt(lossPct) + ' %</b>.';
  }
  R.addEventListener('input', render);
  render();
})();
